{"path": "/tmp/sv-cbb013e39e054710988b2a3790fde8a5/Components/Pages/Catalog.razor", "file_text": "@page "/catalog"
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    <!-- Left Sidebar -->
    <aside class="catalog-sidebar">
        <h4>Filters</h4>

        <div class="filter-section">
            <h5>Categories</h5>
            @if (categories is not null)
            {
                @foreach (var category in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@selectedCategories.Contains(category)"
                               @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                        @category
                    </label>
                }
            }
            else
            {
                <p class="text-muted">Loading categories...</p>
            }
        </div>

        <div class="filter-section">
            <h5>Price Range</h5>
            <label>
                Min Price
                <input type="number" class="form-control" @bind="minPrice" min="0" step="0.01" />
            </label>
            <label>
                Max Price
                <input type="number" class="form-control" @bind="maxPrice" min="0" step="0.01" />
            </label>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="inStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    <!-- Main Content -->
    <main class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="alert alert-danger">@errorMessage</div>
        }
        else if (isLoading)
        {
            <div class="loading-indicator">
                <p>Loading products...</p>
            </div>
        }
        else if (pagedResult is null || pagedResult.Items.Count == 0)
        {
            <div class="empty-results">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else
        {
            <!-- Toolbar -->
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label>Sort by:</label>
                    <select class="form-select" @onchange="OnSortChanged">
                        <option value="price_asc" selected="@(sortBy == "price_asc")">Price: Low to High</option>
                        <option value="price_desc" selected="@(sortBy == "price_desc")">Price: High to Low</option>
                        <option value="name_asc" selected="@(sortBy == "name_asc")">Name: A-Z</option>
                        <option value="rating_desc" selected="@(sortBy == "rating_desc")">Rating: Highest</option>
                    </select>
                </div>
                <div class="results-info">
                    Showing @(((pagedResult.Page - 1) * pagedResult.PageSize) + 1)–@(Math.Min(pagedResult.Page * pagedResult.PageSize, pagedResult.TotalCount)) of @pagedResult.TotalCount products
                </div>
            </div>

            <!-- Product Grid -->
            <div class="product-grid">
                @foreach (var product in pagedResult.Items)
                {
                    <ProductCard Product="product"
                                 OnProductSelected="OnProductSelected"
                                 OnAddToCart="OnAddToCart" />
                }
            </div>

            <!-- Pagination -->
            <nav class="pagination-controls">
                <button class="btn btn-outline-primary"
                        disabled="@(currentPage <= 1)"
                        @onclick="() => GoToPage(currentPage - 1)">
                    Previous
                </button>

                @for (int i = 1; i <= totalPages; i++)
                {
                    var pageNum = i;
                    <button class="btn @(pageNum == currentPage ? "btn-primary" : "btn-outline-primary")"
                            @onclick="() => GoToPage(pageNum)">
                        @pageNum
                    </button>
                }

                <button class="btn btn-outline-primary"
                        disabled="@(currentPage >= totalPages)"
                        @onclick="() => GoToPage(currentPage + 1)">
                    Next
                </button>
            </nav>
        }
    </main>
</div>

@code {
    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;
    private PagedResult<Product>? pagedResult;
    private bool isLoading;
    private string? errorMessage;

    private int totalPages => pagedResult is null || pagedResult.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)pagedResult.TotalCount / pagedResult.PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await SearchProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load categories: {ex.Message}";
        }
    }

    private async Task SearchProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            StateHasChanged();

            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            pagedResult = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await SearchProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await SearchProducts();
    }

    private async Task OnSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await SearchProducts();
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await SearchProducts();
    }

    private async Task OnAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        await Task.CompletedTask;
    }
}
"}

