.catalog-container {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    width: 25%;
    min-width: 220px;
    padding: 1rem;
    border-right: 1px solid #dee2e6;
}

.catalog-sidebar h4 {
    margin-bottom: 1rem;
}

.filter-section {
    margin-bottom: 1.5rem;
}

.filter-section h5 {
    margin-bottom: 0.5rem;
    font-size: 0.95rem;
}

.filter-section label {
    display: block;
    margin-bottom: 0.4rem;
}

.filter-checkbox {
    display: flex !important;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.catalog-main {
    width: 75%;
    padding: 1rem;
}

.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #dee2e6;
}

.sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.sort-control .form-select {
    width: auto;
}

.results-info {
    color: #6c757d;
    font-size: 0.9rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.loading-indicator,
.empty-results {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 200px;
    color: #6c757d;
}

.pagination-controls {
    display: flex;
    justify-content: center;
    gap: 0.3rem;
    flex-wrap: wrap;
}

